-- Synthetic JWT claims exercise PostgreSQL authorization only. This is not a
-- real Auth/provider integration test. The enclosing runner always rolls back.
DO $test$
DECLARE actor uuid:=gen_random_uuid();other_actor uuid:=gen_random_uuid();request uuid:=gen_random_uuid();customer uuid;second uuid;result jsonb;again jsonb;contact jsonb;checks integer:=0;
BEGIN
 IF has_function_privilege('anon','public.sandy_customer_onboarding_execute(text,jsonb,uuid)','EXECUTE') OR has_function_privilege('authenticated','public.sandy_customer_contact_observe(text,text,text)','EXECUTE') OR has_table_privilege('authenticated','public.sandy_customer_provisional_contacts','SELECT') OR has_table_privilege('anon','public.sandy_customer_onboarding_receipts','SELECT') THEN RAISE EXCEPTION 'identity privilege boundary';END IF;checks:=checks+4;
 INSERT INTO auth.users(id,email,email_confirmed_at,is_anonymous,raw_app_meta_data,raw_user_meta_data) VALUES(actor,'sandy-onboarding-'||actor||'@example.invalid',clock_timestamp(),false,'{"provider":"email","providers":["email"]}','{"sandy_api_isolated_session_test":true}'),(other_actor,'sandy-onboarding-'||other_actor||'@example.invalid',clock_timestamp(),false,'{"provider":"email","providers":["email"]}','{"sandy_api_isolated_session_test":true}');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);
 result:=public.sandy_customer_onboarding_execute('customer.onboarding.ensure','{"display_name":"Isolated fixture"}',request);
 IF result->>'ok' IS DISTINCT FROM 'true' OR result->>'created'<>'true' THEN RAISE EXCEPTION 'verified enrollment: %',result;END IF;checks:=checks+1;customer:=(result->>'customer_id')::uuid;
 IF result->>'executed' IS DISTINCT FROM 'true' OR result->>'request_state' IS DISTINCT FROM 'succeeded' OR result->>'request_id' IS DISTINCT FROM request::text OR result->>'reconciliation_required' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'truthful synchronous execution metadata';END IF;checks:=checks+1;
 IF (SELECT google_drive_folder_status FROM public.email_customers WHERE id=customer)<>'excluded' OR EXISTS(SELECT 1 FROM public.sandy_client_drive_provisioning WHERE customer_id=customer) OR EXISTS(SELECT 1 FROM public.sandy_memory_settings WHERE customer_id=customer AND (learning_enabled OR proactive_enabled)) THEN RAISE EXCEPTION 'unentitled automatic side effect';END IF;checks:=checks+3;
 again:=public.sandy_customer_onboarding_execute('customer.onboarding.ensure','{"display_name":"Isolated fixture"}',request);IF again->>'reused'<>'true' OR again->>'customer_id'<>customer::text THEN RAISE EXCEPTION 'idempotent enrollment';END IF;checks:=checks+1;
 UPDATE public.sandy_customer_onboarding_receipts r SET result=r.result-'executed'-'request_state'-'request_id'-'reconciliation_required' WHERE actor_id=actor AND request_id=request;
 again:=public.sandy_customer_onboarding_execute('customer.onboarding.ensure','{"display_name":"Isolated fixture"}',request);IF again->>'executed' IS DISTINCT FROM 'true' OR again->>'request_id' IS DISTINCT FROM request::text THEN RAISE EXCEPTION 'legacy receipt execution compatibility';END IF;checks:=checks+1;
 again:=public.sandy_customer_onboarding_execute('customer.onboarding.ensure','{}',gen_random_uuid());IF again->>'created'<>'false' OR again->>'customer_id'<>customer::text THEN RAISE EXCEPTION 'duplicate customer';END IF;checks:=checks+1;
 again:=public.sandy_customer_onboarding_execute('customer.onboarding.ensure','{"display_name":"different"}',request);IF again->>'error'<>'request_id_conflict' THEN RAISE EXCEPTION 'idempotency argument conflict';END IF;checks:=checks+1;
 again:=public.sandy_customer_onboarding_execute('customer.onboarding.update',jsonb_build_object('expected_version',(result->>'version')::integer,'organisation_name','Fixture organisation'),gen_random_uuid());IF again->>'phase'<>'ready' OR again->>'organisation_name'<>'Fixture organisation' THEN RAISE EXCEPTION 'progressive onboarding';END IF;checks:=checks+1;
 again:=public.sandy_customer_onboarding_execute('customer.onboarding.update','{"expected_version":1,"display_name":"Wrong"}',gen_random_uuid());IF again->>'error'<>'onboarding_version_conflict' THEN RAISE EXCEPTION 'stale profile write';END IF;checks:=checks+1;
 again:=public.sandy_customer_onboarding_execute('customer.identity.get',jsonb_build_object('customer_id',customer),gen_random_uuid());IF again->>'error'<>'invalid_onboarding_arguments' THEN RAISE EXCEPTION 'caller tenant override';END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',other_actor,'role','authenticated')::text,true);
 again:=public.sandy_customer_onboarding_execute('customer.identity.get','{}',gen_random_uuid());IF again->>'error'<>'onboarding_required' THEN RAISE EXCEPTION 'other customer session got identity';END IF;checks:=checks+1;
 UPDATE public.sandy_customer_onboarding_receipts r SET result=r.result-'executed'-'request_state'-'request_id'-'reconciliation_required' WHERE actor_id=actor AND request_id=request;
 again:=public.sandy_customer_onboarding_execute('customer.onboarding.ensure','{"display_name":"Isolated fixture"}',request);IF again->>'executed' IS DISTINCT FROM 'true' OR again->>'request_id' IS DISTINCT FROM request::text THEN RAISE EXCEPTION 'legacy receipt execution compatibility';END IF;checks:=checks+1;
 again:=public.sandy_customer_onboarding_execute('customer.onboarding.ensure','{}',gen_random_uuid());second:=(again->>'customer_id')::uuid;IF second IS NULL OR second=customer THEN RAISE EXCEPTION 'customer isolation';END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);
 INSERT INTO public.sandy_whatsapp_identities(wa_id,customer_id,verification_status,verified_at,allowed_scopes) VALUES('15550000001',customer,'verified',clock_timestamp(),ARRAY['memory_read']),('15550000002',second,'verified',clock_timestamp(),ARRAY['memory_read']),('15550000003',customer,'verified',clock_timestamp()-interval '91 days',ARRAY['memory_read']);
 again:=public.sandy_customer_onboarding_execute('customer.identity.get','{}',gen_random_uuid());IF jsonb_array_length(again->'channels')<>4 OR again::text LIKE '%15550000002%' OR again::text LIKE '%15550000003%' THEN RAISE EXCEPTION 'verified channel projection';END IF;checks:=checks+3;
 UPDATE public.sandy_memory_portal_accounts SET revoked_at=clock_timestamp() WHERE auth_user_id=actor;
 again:=public.sandy_customer_onboarding_execute('customer.onboarding.ensure','{"display_name":"Isolated fixture"}',request);IF again->>'error'<>'customer_access_revoked' THEN RAISE EXCEPTION 'revoked receipt replay';END IF;checks:=checks+1;
 UPDATE public.sandy_memory_portal_accounts SET revoked_at=NULL WHERE auth_user_id=actor;
 UPDATE auth.users SET email='changed-'||actor||'@example.invalid' WHERE id=actor;
 again:=public.sandy_customer_onboarding_execute('customer.onboarding.ensure','{"display_name":"Isolated fixture"}',request);IF again->>'error'<>'identity_link_conflict' THEN RAISE EXCEPTION 'email changed receipt replay';END IF;checks:=checks+1;
 UPDATE auth.users SET raw_app_meta_data='{"sandy_engineering_test":true}' WHERE id=actor;
 again:=public.sandy_customer_onboarding_execute('customer.identity.get','{}',gen_random_uuid());IF again->>'error'<>'verified_customer_session_required' THEN RAISE EXCEPTION 'machine enrollment';END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','service_role')::text,true);
 again:=public.sandy_customer_onboarding_execute('customer.identity.get','{}',gen_random_uuid());IF again->>'error'<>'user_session_required' THEN RAISE EXCEPTION 'administrative key substitution';END IF;checks:=checks+1;
 contact:=public.sandy_customer_contact_observe('whatsapp','+15550009999','isolated-contact-event');again:=public.sandy_customer_contact_observe('whatsapp','15550009999','isolated-contact-event');IF again->>'contact_id'<>contact->>'contact_id' OR again->>'reused'<>'true' OR again->>'authorized'<>'false' THEN RAISE EXCEPTION 'provisional contact deduplication';END IF;checks:=checks+3;
 again:=public.sandy_customer_contact_observe('whatsapp','15550009998','isolated-contact-event');IF again->>'error'<>'provider_event_conflict' THEN RAISE EXCEPTION 'provider event input conflict';END IF;checks:=checks+1;
 again:=public.sandy_customer_contact_observe('email','spoofed address','isolated-invalid-event');IF again->>'error'<>'invalid_contact' THEN RAISE EXCEPTION 'invalid provisional channel';END IF;checks:=checks+1;
 CREATE TEMP TABLE sandy_onboarding_test_report AS SELECT checks passed,0 failed,true rolled_back;
END $test$;
SELECT * FROM sandy_onboarding_test_report;
